{"query": "
query MedalliaIntrospect {
  __schema {
    queryType {
      fields {
        name
        args { name type { ...TypeRef } }
        type { ...TypeRef }
      }
    }
    types {
      name
      kind
      fields {
        name
        args { name }
        type { ...TypeRef }
      }
    }
  }
}
fragment TypeRef on __Type {
  kind
  name
  ofType { kind name ofType { kind name ofType { kind name } } }
}
"}
